// Validation des données d'entrée
const body = $input.first().json.body;

if (!body || !body.fileData) {
  throw new Error('fileData manquant dans la requête');
}
if (!body.periode || !/^\d{2}-\d{4}$/.test(body.periode)) {
  throw new Error('Période invalide. Format requis: MM-YYYY');
}
if (!body.gasUrl) {
  throw new Error('URL Google Apps Script manquante');
}

// Décoder le base64 en buffer
const buffer = Buffer.from(body.fileData, 'base64');

// Vérifier le header PDF
const header = buffer.slice(0, 5).toString('ascii');
const estPDF = header.startsWith('%PDF');

return [{
  json: {
    fileData: body.fileData,
    fileName: body.fileName || 'upload.pdf',
    periode: body.periode,
    gasUrl: body.gasUrl,
    estPDF: estPDF,
    tailleFichier: buffer.length,
    timestamp: new Date().toISOString()
  }
}];

// Récupérer le fileId retourné par GAS
const gasReponse = $input.first().json;
const fileId = gasReponse.fileId || (gasReponse.data && gasReponse.data.fileId) || null;

if (!fileId) {
  throw new Error('GAS n\'a pas retourné de fileId. Réponse : ' + JSON.stringify(gasReponse).substring(0, 200));
}

// Récupérer fileData depuis le nœud de validation (double quotes pour l'apostrophe)
const validationData = $("Validation des données d'entrée").item.json;
const fileData = validationData.fileData;
const gasUrl = validationData.gasUrl;
const periode = validationData.periode;

const buffer = Buffer.from(fileData, 'base64');

let pages = [];

try {
  // SIMULATION — Remplacer par l'extraction réelle en production
  // En production : utiliser pdf-parse ou Google Cloud Document AI
  pages = [
    { pageIndex: 0, texte: 'NOM_Prenom détecté page 1', nomPrenom: '' }
  ];
} catch (error) {
  throw new Error('Erreur extraction PDF: ' + error.message);
}

// Propager gasUrl et periode pour les nœuds suivants
return [{ json: { pages, totalPages: pages.length, fileId, gasUrl, periode } }];

// Faire correspondre chaque page avec un salarié
const extraitData = $("Extraire le texte du PDF").item.json;
const pages = extraitData.pages;
const fileId = extraitData.fileId;
const periode = extraitData.periode;

// La réponse GAS peut être un tableau direct ou encapsulée
const gasReponse = $input.first().json;
let salaries = [];
if (Array.isArray(gasReponse)) {
  salaries = gasReponse;
} else if (Array.isArray(gasReponse.salaries)) {
  salaries = gasReponse.salaries;
} else if (Array.isArray(gasReponse.data)) {
  salaries = gasReponse.data;
}

const resultatsMatching = [];
const nonTrouves = [];
const emailsManquants = [];

for (const page of pages) {
  const salarie = salaries.find(s => s.nomPrenom === page.nomPrenom);

  if (!salarie) {
    nonTrouves.push(page.nomPrenom);
    resultatsMatching.push({ ...page, statut: 'NON_TROUVE', email: null, inclure: false });
  } else if (!salarie.email) {
    emailsManquants.push(page.nomPrenom);
    resultatsMatching.push({ ...page, statut: 'EMAIL_MANQUANT', email: null, idDossierDrive: salarie.idDossierDrive, inclure: true });
  } else {
    resultatsMatching.push({ ...page, statut: 'OK', email: salarie.email, idDossierDrive: salarie.idDossierDrive, inclure: true });
  }
}

return [{
  json: {
    mapping: resultatsMatching,
    nonTrouves,
    emailsManquants,
    nbTotal: resultatsMatching.length,
    nbOk: resultatsMatching.filter(m => m.statut === 'OK').length,
    nbProblemes: nonTrouves.length + emailsManquants.length,
    fileId,
    periode
  }
}];
